import 'package:flutter/material.dart';

/// Scripture is supplied by the academy API, never generated by this widget.
class QuranReader extends StatefulWidget {
  final Future<dynamic> Function(String) fetch;
  const QuranReader({super.key, required this.fetch});
  @override
  State<QuranReader> createState() => _QuranReaderState();
}

class _QuranReaderState extends State<QuranReader> {
  int number = 1, requestId = 0;
  String mode = 'Para', edition = 'Arabic only', query = '', error = '';
  List<dynamic> verses = [], surahs = [];
  Map<int, String> translation = {};
  bool loading = true;
  @override
  void initState() {
    super.initState();
    load();
  }

  Future<void> load() async {
    final id = ++requestId;
    setState(() => loading = true);
    try {
      final part = mode == 'Para' ? 'juz' : 'surah';
      final results = await Future.wait([
        widget.fetch('/quran/$part/$number'),
        if (surahs.isEmpty) widget.fetch('/quran/surahs'),
      ]);
      final translated = edition == 'Arabic only'
          ? null
          : await widget.fetch(
              '/quran/$part/$number?edition=${edition == 'Urdu' ? 'ur.jalandhry' : 'en.sahih'}',
            );
      if (!mounted || id != requestId) return;
      setState(() {
        verses = results.first['verses'] as List;
        if (results.length > 1) surahs = results[1] as List;
        translation = {
          if (translated != null)
            for (final v in translated['verses'] as List)
              v['number'] as int: v['text'] as String,
        };
        error = '';
      });
    } catch (e) {
      if (mounted && id == requestId) setState(() => error = e.toString());
    } finally {
      if (mounted && id == requestId) setState(() => loading = false);
    }
  }

  void select(VoidCallback change) {
    setState(change);
    load();
  }

  @override
  Widget build(BuildContext context) {
    final filtered = verses
        .where(
          (v) =>
              query.isEmpty ||
              '${v['text']} ${translation[v['number']] ?? ''} ${v['surah_english']}'
                  .toLowerCase()
                  .contains(query.toLowerCase()),
        )
        .toList();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Text(
          'The Holy Quran',
          style: TextStyle(
            fontFamily: 'CormorantGaramond',
            fontSize: 34,
            color: Color(0xFF145B45),
          ),
        ),
        const SizedBox(height: 10),
        const Text(
          'All 30 paras · 114 Surahs · Arabic Uthmani text with optional translation',
          style: TextStyle(fontSize: 12, color: Color(0xFF77867D)),
        ),
        const SizedBox(height: 24),
        Wrap(
          spacing: 12,
          runSpacing: 12,
          children: [
            SizedBox(
              width: 140,
              child: DropdownButtonFormField<String>(
                initialValue: mode,
                isExpanded: true,
                items: ['Para', 'Surah']
                    .map(
                      (v) => DropdownMenuItem(
                        value: v,
                        child: Text(v, overflow: TextOverflow.ellipsis),
                      ),
                    )
                    .toList(),
                onChanged: loading
                    ? null
                    : (v) => select(() {
                        mode = v!;
                        number = 1;
                      }),
                decoration: const InputDecoration(labelText: 'Browse by'),
              ),
            ),
            SizedBox(
              width: 240,
              child: DropdownButtonFormField<int>(
                key: ValueKey('$mode-$number-${surahs.length}'),
                initialValue: number,
                isExpanded: true,
                items: List.generate(
                  mode == 'Para' ? 30 : 114,
                  (i) => DropdownMenuItem(
                    value: i + 1,
                    child: Text(
                      mode == 'Para'
                          ? 'Para ${i + 1}'
                          : surahs.length > i
                          ? '${i + 1}. ${surahs[i]['english_name']}'
                          : 'Surah ${i + 1}',
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ).toList(),
                onChanged: loading ? null : (v) => select(() => number = v!),
                decoration: InputDecoration(labelText: mode),
              ),
            ),
            SizedBox(
              width: 180,
              child: DropdownButtonFormField<String>(
                initialValue: edition,
                isExpanded: true,
                items: ['Arabic only', 'Urdu', 'English']
                    .map(
                      (v) => DropdownMenuItem(
                        value: v,
                        child: Text(v, overflow: TextOverflow.ellipsis),
                      ),
                    )
                    .toList(),
                onChanged: loading ? null : (v) => select(() => edition = v!),
                decoration: const InputDecoration(labelText: 'Translation'),
              ),
            ),
          ],
        ),
        const SizedBox(height: 18),
        TextField(
          onChanged: (v) => setState(() => query = v),
          decoration: const InputDecoration(
            labelText: 'Search this selection',
            prefixIcon: Icon(Icons.search),
          ),
        ),
        const SizedBox(height: 18),
        const Text(
          'Unmodified Quran text: Tanzil Project (tanzil.net), served by AlQuran Cloud. Translations: Jalandhry (Urdu), Sahih International (English). Text is cached on the academy computer after its first successful download.',
          style: TextStyle(fontSize: 10, color: Color(0xFF77867D), height: 1.8),
        ),
        const SizedBox(height: 20),
        if (loading)
          const Padding(
            padding: EdgeInsets.all(30),
            child: Center(child: CircularProgressIndicator()),
          )
        else if (error.isNotEmpty)
          Card(
            child: Padding(
              padding: const EdgeInsets.all(22),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(error, style: const TextStyle(height: 1.8)),
                  const SizedBox(height: 14),
                  OutlinedButton.icon(
                    onPressed: load,
                    icon: const Icon(Icons.refresh),
                    label: const Text('Try again'),
                  ),
                ],
              ),
            ),
          )
        else ...[
          Text(
            '$mode $number · ${verses.length} ayahs',
            style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600),
          ),
          const SizedBox(height: 18),
          if (filtered.isEmpty)
            const Text('No matching ayahs in this selection.'),
          for (final v in filtered)
            Card(
              color: Colors.white,
              elevation: 0,
              margin: const EdgeInsets.only(bottom: 16),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(14),
                side: const BorderSide(color: Color(0xFFE4EADF)),
              ),
              child: Padding(
                padding: const EdgeInsets.all(22),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      '${v['surah_english']} · ${v['surah']}:${v['ayah']} · Para ${v['juz']}',
                      style: const TextStyle(
                        fontSize: 11,
                        color: Color(0xFF77867D),
                      ),
                    ),
                    const SizedBox(height: 16),
                    SelectableText(
                      v['text'] as String,
                      textDirection: TextDirection.rtl,
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontFamily: 'NotoNaskhArabic',
                        fontSize: 30,
                        height: 2.1,
                        color: Color(0xFF143B30),
                      ),
                    ),
                    if (translation.containsKey(v['number'])) ...[
                      const Divider(height: 30),
                      SelectableText(
                        translation[v['number']]!,
                        textDirection: edition == 'Urdu'
                            ? TextDirection.rtl
                            : TextDirection.ltr,
                        textAlign: edition == 'Urdu'
                            ? TextAlign.right
                            : TextAlign.left,
                        style: TextStyle(
                          fontFamily: edition == 'Urdu'
                              ? 'NotoNaskhArabic'
                              : 'Manrope',
                          fontSize: edition == 'Urdu' ? 22 : 15,
                          height: 1.9,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
          Wrap(
            alignment: WrapAlignment.spaceBetween,
            spacing: 12,
            runSpacing: 12,
            children: [
              OutlinedButton(
                onPressed: number > 1 ? () => select(() => number--) : null,
                child: Text('Previous $mode'),
              ),
              OutlinedButton(
                onPressed: number < (mode == 'Para' ? 30 : 114)
                    ? () => select(() => number++)
                    : null,
                child: Text('Next $mode'),
              ),
            ],
          ),
        ],
      ],
    );
  }
}
